package com.example.demo;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

record NouveauLivre(String titre) {}

@RestController
class AtelierController {
  @PostMapping("/livres")
  @ResponseStatus(HttpStatus.CREATED)
  String creer(@RequestBody NouveauLivre entree) {
    if (entree == null || entree.titre() == null || entree.titre().isBlank())
      throw new IllegalArgumentException("titre requis");
    return entree.titre().trim();
  }
}

package com.example.demo;

import org.springframework.stereotype.Service;

@Service
class PrixService {
  int total(int prix, int quantite) {
    if (prix < 0 || quantite < 0) throw new IllegalArgumentException("valeur négative");
    return Math.multiplyExact(prix, quantite);
  }
}

